#include <iostream>
#include <vector>
using namespace std;

int n;
vector<int> d;

string check2() {
    int nowpos = n - 1;
    int canhop = n - 1;
    int minhop = n - 1;

    for (int j = 0; j < n; j++) { // Adjusted iterations to n instead of 100000
        canhop = nowpos - d[nowpos] / 10;
        minhop = canhop;
        if (canhop <= 0) return "yes";

        for (int i = nowpos; i >= canhop; i--) {
            if (i - d[i] / 10 < minhop) {
                nowpos = i;
                minhop = i - d[i] / 10;
                if (minhop <= 0) return "yes"; // Early exit
            }
        }
    }
    return "no";
}

string check1() {
    int nowpos = 0;
    int canhop = 0;
    int maxhop = 0;

    for (int j = 0; j < n; j++) { // Adjusted iterations to n instead of 100000
        canhop = d[nowpos] / 10 + nowpos;
        maxhop = canhop;
        if (canhop >= n - 1) return check2();

        for (int i = nowpos; i <= canhop; i++) {
            if (d[i] / 10 + i >= maxhop) {
                nowpos = i;
                maxhop = d[i] / 10 + i;
                if (maxhop >= n - 1) return check2(); // Early exit
            }
        }
    }
    return "no";
}

int main() {
    scanf("%d", &n);
    d.resize(n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &d[i]);
        d[i] -= d[i] % 10; // Removing last digit
    }
    printf("%s\n", check1().c_str());
    return 0;
}

